#include "content.h"
#include <srvros/desktop_protocol.h>
#include <string.h>
#define T(id,text) {id,DESK_DOCUMENT_TITLE,text}
#define H(id,text) {id,DESK_DOCUMENT_HEADING,text}
#define P(id,text) {id,DESK_DOCUMENT_PARAGRAPH,text}
#define N(id,text) {id,DESK_DOCUMENT_NOTE,text}
#define C(id,text) {id,DESK_DOCUMENT_CODE,text}
static const struct desk_document_block welcome[]={
 T(1,"Welcome to SrvrOS"),P(2,"A small desktop, built from the ground up. Open a tool, arrange your workspace and make something. This guide travels with the system and works without a network connection."),
 H(3,"Find your way"),P(4,"The dock opens Files, Text, Calculator, System, Settings and Terminal. Press Command-Space to search for any application or an open window. Preview, Sketch, Clock and Help are available there too."),
 H(5,"Start with a document"),P(6,"Open Text, type a few lines and choose File > Save. In a laptop trial, Home is the saved USB workspace at /work/srvros-work. Other sessions use /fat/home. Files can open saved text and images with the appropriate application."),
 H(7,"Make it yours"),P(8,"Settings offers larger text, wallpaper colors and clock preferences. The global menu follows the active application. Click the clock to open the calendar."),
 H(9,"Using this guide"),P(10,"Choose Topics or press Ctrl-L to search the guide. Back and Forward restore the page and your scroll position. Copy page puts a plain-text copy on the shared clipboard. Open app starts the tool described by the current topic."),
 N(11,"Press F1 in an application to open its help topic. For keyboard controls, search Topics for Keyboard.")};
static const struct desk_document_block desktop[]={
 T(1,"Your desktop"),H(2,"Applications and windows"),P(3,"Click a dock icon to open its application or focus an existing window. Command-Space opens the launcher: type a name, use Up or Down to choose a result, then Enter to open it. Escape dismisses the launcher."),
 P(4,"Drag a window by its title bar. Drag its lower-right corner to resize it. Every app has three title-bar buttons on the right: minimize (line), maximize or restore (square), and close (cross). Maximize fills the usable desktop; clicking it again restores the previous size and position. The global Window menu lists open windows and offers the same window actions."),
 H(5,"Focus and menus"),P(6,"Click a window to focus it, or press Alt-Tab to cycle forward and Alt-Shift-Tab to cycle backward. F10 focuses the menu bar. Use arrows to choose a heading or action, Enter to activate and Escape to dismiss. Right-click or Control-click opens contextual actions; Shift-F10 or the Menu key opens them for the focused control. The desktop background has its own application menu."),
 H(7,"Scrolling"),P(8,"Two-finger trackpad scrolling and the mouse wheel scroll the view beneath the pointer. You can also drag scrollbar thumbs. Inside a focused list or document, use arrows, Page Up, Page Down, Home and End."),
 H(9,"The clock and calendar"),P(10,"Click the clock to browse the calendar. Arrow keys move by day or week, Page Up and Page Down change month, and Ctrl-Home returns to today. Settings controls the clock format, date display and fixed UTC offset."),
 H(16,"Arrange your workspace"),P(17,"Arrange > Tile left or Tile right places the active window beside another. Command-Alt-Left and Command-Alt-Right do the same. Switching sides preserves its original size and position. Window > Restore size or Command-Alt-Down returns it there; the same shortcut maximizes a normal window. Arrange > Center or Command-Alt-Up centers the original window size. Tiling keeps clear of the menu and dock and is disabled when the display is too small."),
 H(11,"Finishing a session"),P(12,"Choose SrvrOS > Return to console. Applications can ask you to save unfinished work before they close. Ctrl-Alt-Escape exits the desktop immediately and should be reserved for a stuck session."),
 H(13,"Screenshots"),P(14,"Command-Shift-3 or SrvrOS > Save screenshot captures the whole desktop, including its pointer. Saving runs in the background. The completion notification opens the Screenshots folder inside Home; choose a BMP there to view it in Preview. Capture supports displays whose BMP fits within 8 MiB, including full HD. Return to console waits for a pending save; immediate exit may abandon an incomplete capture."),N(15,"The desktop currently reserves eight application-window slots and their drawing buffers. This is an early software limit, not a hardware limit. Close a window if there is no room to open another.")};
static const struct desk_document_block files[]={
 T(1,"Files"),P(2,"Browse folders, open documents and manage individual files. Home opens your session document folder: the USB workspace during a laptop trial, or /fat/home otherwise. Startup disk opens /fat, and System root shows all mounted locations."),
 H(3,"Go somewhere"),P(4,"Press Ctrl-L to edit the location, type an absolute path and press Enter. Alt-Left and Alt-Right move through visited folders; Alt-Up opens the parent; Alt-Home opens Home. Ctrl-R refreshes the listing. Ctrl-F opens Find Files at this folder for a recursive name search."),
 H(5,"Open and organize"),P(6,"Select a row, then use Open or press Enter. Folders open in Files; PNG, JPEG and BMP images open in Preview; other files open in Text. New folder, Rename, Duplicate and Delete are available from the controls and menus."),
 P(7,"Duplicate copies an individual file up to 16 MiB and verifies its contents before reporting success. Delete removes an individual file or an empty folder after confirmation. There is no Trash or automatic recovery of deleted files."),
 H(8,"Paths and volumes"),P(9,"A path beginning with / is absolute. /fat is the main exFAT volume in this desktop environment. Other mounted volumes appear at their assigned paths. Files does not format, partition or automatically mount drives."),
 H(11,"Information and paths"),P(12,"Select an item and press Ctrl-I or choose Information from File or its contextual menu. This reads current metadata without loading file contents. Copy path copies its absolute path; Copy details exports the displayed metadata. Ctrl-C copies details and Ctrl-Shift-C copies the path. Escape returns to Files. Close and reopen to refresh; folder contents are not totaled."),
 N(10,"A failed operation leaves a message in the window. Check the destination, free space and whether the volume is writable before trying again.")};
static const struct desk_document_block text[]={
 T(1,"Text"),P(2,"Write and edit plain UTF-8 documents. The editor supports selection, a shared clipboard, search and multiple steps of Undo and Redo."),
 H(3,"Open and save"),P(4,"Ctrl-N creates a document. Ctrl-O opens the file picker. Ctrl-S saves the current document; Ctrl-Shift-S chooses a new path. Closing an edited document asks whether to save, discard or cancel."),
 P(5,"The file picker accepts a folder location and a filename. Saving checks for a file that changed since it was opened and asks before overwriting an existing destination."),
 H(6,"Edit"),P(7,"Ctrl-A selects all; Ctrl-X cuts; Ctrl-C copies; Ctrl-V pastes. Ctrl-Z undoes and Ctrl-Shift-Z redoes. Shift with navigation keys extends the selection. Click and drag to select text. Scroll with the trackpad or drag the vertical and horizontal scrollbar thumbs. Scrolling keeps the selection; typing or keyboard navigation brings the caret back into view. Right-click or Control-click opens editing actions while preserving your selection; Shift-F10 opens the same menu from the keyboard."),
 H(8,"Find text"),P(9,"Ctrl-F opens Find. Ctrl-G moves to the next match and Ctrl-Shift-G to the previous one. The search bar shows the result and offers case-sensitive matching. Escape closes it."),
 H(13,"Replace text"),P(14,"Ctrl-H opens Find and Replace. Enter a literal Find value and a With value; an empty With removes matching text. Replace changes the selected match and finds the next. Replace all changes every nonoverlapping match in the original document as one undo step. Enter in With replaces one; Ctrl-Enter replaces all. A replacement that would exceed the document limit makes no changes. Escape returns to the document; Undo then restores the edit."),
 H(10,"Working limits"),P(11,"Documents are limited to 64 KiB. Undo history is bounded to 256 records and 256 KiB of edit data; the oldest entries are dropped when it fills. Saving keeps Undo history, while opening a different document starts a new history."),
 N(12,"UTF-8 text is preserved, but the current fonts cover a limited set of characters. A replacement glyph means the font cannot display that character; it does not mean the saved text was replaced.")};
static const struct desk_document_block calculator[]={
 T(1,"Calculator"),P(2,"Type an expression or use the keypad. Press Enter or Equals to calculate. Parentheses and the four basic arithmetic operations are supported."),
 H(3,"Continue a calculation"),P(4,"After a result, type an operator to continue with that value or type a digit to begin again. Ans inserts the previous answer. The plus/minus control changes the sign."),
 H(5,"Use a previous result"),P(6,"The session history holds the latest 16 calculations. Select a row and choose Use to bring its result into the expression, or Copy result to put it on the clipboard."),
 H(7,"Precision"),P(8,"Calculations use floating-point numbers and display up to 12 significant digits. The expression field holds up to 255 bytes. Very large or very small values can overflow or underflow; an error leaves the expression available to edit."),
 N(9,"History belongs to this window and is not saved after it closes.")};
static const struct desk_document_block terminal[]={
 T(1,"Terminal"),P(2,"Run command-line tools in a terminal window. Each window owns a separate shell and pseudo-terminal. Resize the window to change the terminal dimensions."),
 H(3,"A few commands"),C(4,"pwd\nls /fat/home\ncat /fat/home/example.txt\nps\ndate"),
 H(5,"Input and clipboard"),P(6,"Ctrl-C interrupts the foreground command. Ctrl-Shift-C copies selected terminal text; Ctrl-Shift-V pastes. Command-C and Command-V are also available. Clipboard text is sent as input to the shell, so review commands before pressing Enter."),
 H(7,"The shell environment"),P(8,"Programs are searched in /fat/bin, / and /fat. HOME and the initial shell folder match the desktop Home: /work/srvros-work during a laptop trial, or /fat/home otherwise. Pipes and redirection let you combine tools."),
 C(9,"seq 1 10 | wc -l\necho hello > /fat/home/greeting.txt"),
 H(10,"Closing"),P(11,"Type exit to leave the shell. Closing the window while its shell is running asks for confirmation. This terminal does not yet provide full Unix job control or saved shell history.")};
static const struct desk_document_block preview[]={
 T(1,"Preview"),P(2,"Open PNG, JPEG and BMP images. Choose one in Files or press Ctrl-O in Preview to browse. Decoding runs in a separate worker so the desktop can continue handling input. Ctrl-E or File > Edit in Sketch opens the current image in the drawing tool."),
 H(3,"Look closer"),P(4,"Fit or 0 fits the image inside the window without enlarging a small image. 1:1 or 1 displays one image pixel per screen pixel. Plus and Minus step through zoom levels from 6.25% to 400%."),
 P(5,"Drag to pan a zoomed image. Scrolling and arrow keys move around it; Page Up, Page Down, Home and End offer larger movements. Transparent pixels appear over a checkerboard."),
 H(6,"Opening another image"),P(7,"Cancel or Escape stops an in-progress opening. The previous image remains visible if the new file cannot be opened. Open is available again after the canceled worker has finished closing."),
 H(8,"Supported images"),P(9,"Files may be up to 8 MiB, with at most 4,194,304 pixels and 4096 pixels along either side. Preview displays a still image and does not edit or export it."),
 N(10,"EXIF orientation, color profiles, animation and smooth resampling are not implemented yet. Some photographs may need manual rotation in another tool before opening here.")};
static const struct desk_document_block settings[]={
 T(1,"Settings"),P(2,"Choose a comfortable text size, wallpaper, clock format and trackpad speed. Preferences are shared with open applications."),
 H(3,"Appearance"),P(4,"Standard and Larger adjust the desktop body text. Sage, Sand and Slate change the desktop wallpaper color. Applications reflow their controls where space permits."),
 H(5,"Clock"),P(6,"Choose a 12-hour or 24-hour clock and whether to show the date. The UTC offset changes in 15-minute steps. This is a fixed offset, so daylight-saving changes must be applied manually."),
 H(7,"Saving preferences"),P(8,"The window reports whether changes were saved. If saving fails, the preferences may still be active for this session but will not necessarily survive a restart. In the laptop trial, preferences are saved on the prepared USB workspace and survive a reboot. Other desktop sessions use /fat/home/desktop.conf; a RAM-backed /fat does not survive reboot."),
 H(9,"Trackpad"),P(10,"Scroll down to Trackpad speed. Slow movement stays precise; Accelerate fast swipes increases travel when you move quickly. Try a few speed levels or turn acceleration off for a fixed response. Two-finger scrolling keeps its own speed. Disable while typing is off by default, so typing and pointer movement work together. Turn it on to pause incidental touches while using the built-in keyboard. Lift your fingers to resume after typing; deliberate physical clicks and drags still work. Tap to click uses one finger; Two-finger tap to right-click opens context menus when both fingers lift. Physically clicking with two fingers also right-clicks, even with tapping off. The button stays the same until release: hold a one-finger click first, then add a second finger to steer a left drag. Both tap options start on and can be switched off separately. Move two fingers to scroll, or press the physical click to drag. Long holds and scrolling do not count as taps. Palm rejection stays active. These controls affect the built-in Apple trackpad."),
 N(11,"Settings does not configure storage, networking, accounts or power management."), H(18,"Display brightness"),P(19,"On supported laptop trials, the brightness slider below Trackpad adjusts the built-in display from 5 to 100 percent. Changes apply to this session and do not change the display mode. Other systems show unavailable. Startup leaves brightness unchanged; it is not saved with desktop preferences."),
 H(20,"Sound"),P(21,"Scroll below Display brightness for Sound. A supported audio controller offers an output-volume slider, Speakers or Headphones, Test sound and Stop. Test sound plays a short tone; startup is silent. Start at a low volume. The connection label reports whether headphones are detected; output selection is manual. Plug in headphones before selecting Headphones, and select Speakers again after unplugging them. Volume and output apply only to this session. Terminal can play 44100 or 48000 Hz, 16-bit mono or stereo PCM WAV files with playwav. Set volume and output before starting; Stop cancels file playback. Other sound controls are disabled while a file owns the output. Microphone recording is not enabled."),
 N(22,"Unavailable means no supported audio device was found. Not enabled means this boot did not request audio. A device error disables playback for the rest of the session; diagnostics are retained in the laptop trial logs.")};
static const struct desk_document_block system[]={
 T(1,"System and network status"),P(2,"System provides a live view of processes and network status. Switch between the Processes, Network, Devices and Sensors tabs. Pause freezes the display; Refresh or F5 takes a new snapshot."),
 H(14,"Sensors"),P(15,"Sensors shows cached CPU core and package temperatures, plus fan speed on supported Macs. The matched two-fan MacBook Pro shows L and R speeds together. The core reading is for the boot CPU. Readings update every second; an expired sample becomes unavailable rather than looking current. These are read-only readings. Battery and AC values remain unavailable. Fan speed is a read-only measurement; this page does not control fans or charging."),
 H(12,"Devices"),P(13,"Devices lists the PCI functions and USB devices found during this boot, with vendor/product identifiers. Detected means the hardware was found; it does not mean a driver supports it. Driver active identifies a bound USB function such as a keyboard, trackpad, storage or supported USB Ethernet device. Attach new adapters before booting for this initial inventory. Refresh updates the cached state without resetting or probing devices."),
 H(3,"Processes"),P(4,"The process table lists the running programs and their current state. It is a read-only view; use the command-line tools when a process must be managed."),
 H(5,"Network"),P(6,"The Network tab reports the available interface, link state, MAC and IPv4 addresses, router, DNS configuration and packet counters. A disconnected or unavailable interface is reported explicitly."),
 H(7,"Configuration"),P(8,"Open Diagnostics for background Ping and DNS lookup with copyable reports. Network lists each supported adapter with its driver, hardware address, link and active or inactive role. Only the active adapter has IP configuration; others do not carry application traffic. Adapter numbers last for this boot. Network configuration remains a console task. Available tools include ifconfig, route, arp, ping, host and netstat. The virtual machine can exercise the supported emulated adapter; support for a particular USB network adapter depends on its driver."),
 N(9,"An interface being present does not by itself prove that DNS or Internet access works. Check the address and route, then test the destination you need.")};
static const struct desk_document_block keyboard[]={
 T(1,"Keyboard shortcuts"),H(2,"Across the desktop"),C(3,"Command-Space    Applications and windows\nAlt-Tab          Next window\nAlt-Shift-Tab    Previous window\nF10              Global menu bar\nShift-F10        Contextual actions\nF1               Help for the active application\nCommand-Shift-N  Notifications\nCommand-Shift-3  Save screenshot"),
 H(4,"Inside controls"),P(5,"Tab moves to the next control and Shift-Tab moves backward. Space activates a focused button. Arrow keys navigate lists and documents. Page Up and Page Down scroll a page; Home and End move to an edge. Escape dismisses a dialog or chooser."),
 H(6,"Text editing"),C(7,"Ctrl-A           Select all\nCtrl-X / C / V   Cut / Copy / Paste\nCtrl-Z           Undo\nCtrl-Shift-Z     Redo\nCtrl-F           Find in Text\nCtrl-G           Next match\nCtrl-Shift-G     Previous match"),
 H(8,"Files and documents"),C(9,"Ctrl-O           Open\nCtrl-S           Save in Text\nCtrl-Shift-S     Save as in Text\nCtrl-L           Location in Files; Topics in Help\nCtrl-I           Information in Files\nAlt-Left/Right   Back / Forward\nCtrl-W           Close window"),
 H(10,"Terminal"),P(11,"Use Ctrl-Shift-C and Ctrl-Shift-V for its clipboard. Ctrl-C remains the command interrupt key. Command-C and Command-V are also supported."),
 N(12,"On the MacBook keyboard, Command is the Meta modifier. Depending on the keyboard or virtual machine, function keys may require Fn. Application menus show their available shortcuts.")};
static const struct desk_document_block limits[]={
 T(1,"Current scope"),P(2,"SrvrOS is an evolving native operating system and desktop. Its applications share a widget library, event handling, menus, clipboard and file pickers. This guide describes the implemented features, not a compatibility promise for another desktop system."),
 H(3,"Documents and windows"),P(4,"There are eight application-window slots. Text documents are limited to 64 KiB; Files can duplicate individual files up to 16 MiB. The clipboard holds up to 64 KiB. Preview has separate image limits listed in its topic."),
 H(5,"Text and language"),P(6,"The current UI fonts include ASCII, Latin-1 and selected punctuation. UTF-8 bytes are preserved in documents, but complex text shaping, bidirectional layout, input methods and broad Unicode font fallback are not implemented."),
 H(7,"Desktop services"),P(8,"There is no Trash, application installation interface, browser, sound mixer, full account manager or automatic timezone database yet. Networking and additional hardware depend on the available drivers and console tools."),
 H(9,"Testing"),P(10,"Virtual-machine tests exercise application behavior and failure paths. They do not replace checks on the physical laptop, particularly for storage, input timing, power management and device drivers."),
 N(11,"Save work before ending a session. A destructive file operation does not have a desktop undo or recovery facility.")};
static const struct desk_document_block about[]={
 T(1,"SrvrOS"),P(2,"A native operating system and a quiet, practical desktop. Built from scratch, with the MacBook Air as its first physical desktop target."),
 H(3,"One shared toolkit"),P(4,"Applications use the same buttons, text fields, lists, tables, tabs, scrollbars, dialogs, file pickers, image views, property views, document views, sliders, drawing canvases, color panels and contextual menus. The desktop supplies window management, global menus, a launcher, calendar and clipboard."),
 H(5,"Included tools"),P(6,"Files, Text, Calculator, System, Settings, Terminal, Preview, Sketch, Clock, Network Utility and Help. Open app below opens System for a view of running processes and network status."),
 H(7,"Acknowledgments"),P(8,"The desktop uses DejaVu fonts. Preview uses the stb_image decoder under its MIT license. The source repository includes upstream licenses and records local changes."),
 N(9,"This is a development system. Hardware acceptance and virtual-machine validation are tracked separately in the project documentation.")};
static const struct desk_document_block clock_guide[]={
 T(1,"Clock"),P(2,"Keep a countdown timer and a stopwatch in one window. Both use monotonic time, so changing the displayed wall clock or UTC offset does not change their elapsed time."),
 H(3,"Set a timer"),P(4,"Enter a duration as seconds, m:ss or h:mm:ss, from one second to 24 hours. Start begins counting down. Pause and Resume keep the remaining time; Reset stops the timer and restores its duration. Again repeats a completed timer."),
 H(5,"Time a task"),P(6,"Choose Stopwatch, then Start. Lap records the elapsed time and the split since the previous lap. The latest 64 laps are retained. Pause stops accumulation, Resume continues it, and Reset clears a paused stopwatch and its laps."),
 H(7,"Copy and keyboard controls"),P(8,"Copy puts the displayed time on the clipboard. Copy laps in the Clock menu exports a tab-separated table. Ctrl-1 selects Timer, Ctrl-2 selects Stopwatch, Ctrl-Enter starts or pauses, Ctrl-R resets and Ctrl-L records a lap. Ctrl-Shift-C copies time; Ctrl-Shift-L copies laps."),
 H(9,"Work in another window"),P(10,"Minimize Clock to keep timing while you work. A completed timer shows a brief notification without taking focus. Alerts in the menu bar, SrvrOS > Notifications or Command-Shift-N opens the session history. Open app returns to the source window when it is still open; otherwise it starts the application."),
 P(11,"Click a notification's close button to dismiss its banner. The history retains up to 16 notices, with at most four from one window. Clear removes a selected notice and Clear all empties the history. Opening history marks its notices as read."),
 N(12,"Closing Clock stops its timer and stopwatch; the window asks first while either is running. Timers, laps and notifications are not saved across sessions. There is no audible alarm or suspend/resume guarantee. The stopwatch stops at 100 hours.")};
static const struct desk_document_block sketch_guide[]={
 T(1,"Sketch"),P(2,"Draw on a blank 640 by 360 canvas, or open a PNG, JPEG or BMP image. Sketch uses the shared color panel, sliders, canvas and image workers."),
 H(3,"Draw and navigate"),P(4,"Choose Pen, Line or Box, then drag on the canvas. B, L and R select those tools. Pan (H), wheel scrolling and arrow keys move a zoomed canvas. Plus and minus zoom; 0 fits and 1 shows actual pixels. The Size slider sets a 1 to 32 pixel brush. Paint with white to erase."),
 H(5,"Choose a color"),P(6,"Color or Ctrl-K opens the RGB panel. Drag a channel slider, or use arrow keys, Page Up/Down and Home/End. Shift with an arrow changes ten units. Choose a swatch for a preset. Copy puts the hex color on the clipboard. Use applies the draft; Cancel keeps the previous brush color."),
 H(7,"Undo and cancel"),P(8,"Each completed stroke, line, box or clear is one undo step. Ctrl-Z undoes and Ctrl-Shift-Z redoes; the latest four steps are retained. A new edit discards redo. Escape, focus loss or resize cancels an unfinished stroke or shape. Edit > Clear canvas fills white and can be undone."),
 H(9,"Save a copy"),P(10,"Ctrl-S writes a new BMP copy through a background worker and verifies the saved bytes. Choose a filename ending in .bmp. Existing files are kept; use a different name. Drawing can continue during saving, and newer changes remain marked unsaved. New, Open and Close ask what to do with unsaved work. Imports retain their original files."),
 N(11,"Sketch flattens transparent images onto white and saves opaque BMPs. Its image size must fit an 8 MiB BMP; inputs also follow Preview's format limits. There are no layers, text objects, selections, flood fill or pressure-sensitive brushes yet.")};
#define TOPIC(id,alias,title,detail,app,data) {id,alias,title,detail,app,data,sizeof(data)/sizeof(*data)}
static const struct desk_document_block network_guide[]={
 T(1,"Network Utility"),P(2,"Run a small connection diagnostic while the desktop stays responsive. Open Network Utility from the launcher or the Diagnostics control in System."),
 H(3,"Ping and DNS"),P(4,"Ping sends four echo requests to an IPv4 address or host. DNS lookup asks the configured DNS server for one IPv4 address. Enter a target without spaces or options, then press Run or Ctrl-Enter. Ctrl-L selects the target; Ctrl-1 chooses Ping and Ctrl-2 chooses DNS lookup."),
 H(5,"Work in another window"),P(6,"Diagnostics run in a separate process. You can type in another app or prepare a new target while a diagnostic runs; the report retains the target used for that run. Stop or Escape cancels it. A run has a 15-second deadline. Closing the window stops its diagnostic."),
 H(7,"Keep a report"),P(8,"Copy report or Ctrl-Shift-C copies the operation, target, completion state and output. Paste into Text to save it. Diagnostic > Clear results clears this window. Results are kept only for the current session, and output is limited to 4095 bytes."),
 N(9,"The utility reports when no supported adapter, network link or IPv4 configuration is available. System shows current link state and speed separately from configured addresses. Diagnostics use the active adapter, which is named in the copied report. A successful ping checks reachability to that target; it does not test every Internet service.")};
static const struct desk_document_block find_guide[]={
 T(1,"Find Files"),P(2,"Search file and folder names within a location and its subfolders. Open Find Files from the launcher, SrvrOS menu or Command-Shift-F. In Files, Ctrl-F starts with the displayed folder."),
 H(3,"Choose a search"),P(4,"Enter part of a name and an absolute folder path, then Search or Ctrl-Enter. Matching is literal, including punctuation; ASCII letters ignore case. File contents are not searched. Ctrl-F selects the name field and Ctrl-L selects the location. Choose All items, Files or Folders; Ctrl-1, Ctrl-2 and Ctrl-3 also switch kinds."),
 H(5,"Use a result"),P(6,"Select a result and press Enter to open it in its normal application. Show in Files or Ctrl-R opens its containing folder. Copy path or Ctrl-C copies the complete path. Click a heading to sort; F6 selects headings for keyboard sorting. Right-click or Shift-F10 opens the result menu."),
 H(7,"Background work"),P(8,"Search runs in a separate process. You can keep using the desktop or edit fields for the next search. The results retain the search that produced them. Stop or Escape cancels; closing the window also stops its worker."),
 N(9,"The first 256 matches are shown; a notice appears when more exist. Paths must fit within 159 UTF-8 bytes, and skipped paths are reported. Searches reflect the currently mounted VFS; they are not an index or an atomic filesystem snapshot. Missing or changed results can fail to open. The search deadline is 60 seconds. Small windows keep kind selection in the menu and keyboard shortcuts.")};
static const struct desk_document_block laptop_trial[]={
 T(1,"Laptop desktop trial"),
 H(34,"Headphones, Ethernet and right-click checks"),
 P(35,"For this focused round, open Terminal with Command-Space and enter sh /fat/share/examples/device-checks.sh and press Return. Keep this Help open if useful. The script guides speaker/headphone listening, Ethernet unplug/reconnect and secondary press/tap checks, and saves your typed observations in Home/device-checks. That new folder must not already exist; reruns refuse to overwrite results. Each prompt waits for you without a deadline. Choose low volume and the output manually in Settings. Keep the flash drive and USB adapter attached; unplug only the Ethernet cable when asked. There is no automatic reboot."),
 P(36,"The six-second audio sample plays left, right, then both. Start with headphones unplugged; the script tells you when to connect them. Report missed steps as skipped, never pass. Network completion only means the sequence finished; DHCP/DNS/HTTP results need inspection. Physical two-finger press requires both fingers down before pressing; two-finger tap requires lifting both without pressing. At the end save a screenshot, press Ctrl-Alt-Escape, wait for USB unmounted=yes and type reboot. Battery monitoring is intentionally off in this focused device profile; its accepted ordinary session is retained as recovery."),
 P(2,"Take your time: this session has no deadline and will not reboot itself. Keep this guide open, or reopen Help and search Topics for Laptop trial. Scroll down for the full checklist."),
 H(27,"Ethernet: DNS, HTTP and cable recovery"),
 P(28,"The network trial opens Terminal automatically. It saves the connected checks, waits for you to unplug only the Ethernet cable and press Enter, saves the disconnected checks, then waits for reconnect and Enter before saving the recovered checks. Both prompts wait indefinitely. Keep the USB adapter and workspace plugged in."),
 P(29,"Reports are saved in Home as network-before.txt, network-down.txt and network-after.txt. A completed marker in network-trial.txt means the sequence finished, not that networking passed. Check DHCP/DNS/HTTP status codes and the actual HTTP response. System and Network Utility remain available for visual checks."),
 P(30,"To repeat manually in Terminal: sh /fat/share/examples/network-trial.sh"),
 H(31,"Return after the test"),
 P(32,"Press F10, End, Return to return to console. Wait for USB unmounted=yes, then type reboot and press Return. The trial does not reboot itself."),
 H(25,"Start here: pointer, click and return"),P(26,"For the cursor timing trial, move continuously in circles for about 15 seconds over empty desktop, then over Text. Drag a window for another 15 seconds. Compare response and report any pauses. Timings are saved when you Return to console. For the brightness trial, open Settings and find Display brightness below Trackpad. Try 25, 50 and 75 percent; check that the panel visibly changes and input remains responsive, then return to a comfortable level. Startup leaves brightness unchanged. For the sound trial, open Sound below Display brightness, start at 25 percent and choose Test sound. Check both speakers, then Stop. If you have wired headphones, select Headphones and test at low volume; speakers should be silent. Return to Speakers after unplugging. Scroll to Sound checks below for the stereo WAV command. Sound is unavailable in brightness-only trials. First move one finger on the built-in trackpad and check the pointer in every direction. Physically click, drag this Help window, lift your finger, and try again. Then try two-finger scrolling. These are hardware checks: report anything that does not work. If the pointer does not move, you can still finish using the keyboard: press F10, then End, then Return to choose Return to console. After the console reports USB unmounted=yes, type reboot and press Return. There is no time limit. Scroll below for typing, saving and additional checks."),
 H(3,"1. Open and arrange"),P(4,"Command-Space opens the launcher. Try Text, Files and Terminal. Drag and resize windows. Try the middle title-bar button to maximize each app, click again to restore it, then try minimize and Alt-Tab. Command-Alt-Left/Right tiles a window; Command-Alt-Down restores it. Check two-finger scrolling and dragging scrollbar thumbs."),
 H(14,"Trackpad checks for this round"),P(15,"Press and hold the physical click with one finger, keep it still, and move a second finger to drag a titlebar, text selection or scrollbar thumb. Lift and replace the moving finger several times, then swap which finger moves. Release the click: the drag must end, and fresh two-finger movement must scroll normally. Repeat while Terminal prints seq 1 2000. No jumps, extra clicks or stuck drags should occur. Try a short one-finger tap to select, then a short two-finger tap over a file, a text selection and empty desktop space. Each should open the appropriate context menu without first selecting or activating something else. Also press the physical button with two fingers over a file or empty desktop: a context menu should open. Lift one finger before releasing; no left click should appear. Start a left drag with one finger before adding the steering finger. Try slightly staggered taps, slow holds, movement, and physical clicks: no extra click should follow a scroll or a physical click. In Settings, switch each tap option off and on separately, then leave both on. Tap dragging is not enabled yet. Keep Help open and scroll quickly up and down with two fingers. Repeatedly add and lift a second finger, then switch apps and repeat. Windows should stay open. If one disappears, note the app and gesture. In Settings, scroll to Trackpad speed: compare slow precise moves, fast swipes, and acceleration off. Try dragging and resizing after each change; check that scrolling feels unchanged. Leave Disable while typing off and type while moving the pointer. Turn it on, type while touching the pad, then lift and touch again. Turn it off again to restore simultaneous typing and movement."),
 H(5,"2. Type and edit"),P(6,"In Text, type several lines with AaZz09 and punctuation. Try held keys, Shift, Caps Lock, selection, Ctrl-C/Ctrl-V, Undo and Find/Replace. Open a second Text window by searching Text new app; copy text between them."),
 H(7,"3. Save on the flash drive"),P(8,"Use File > Save as. The location now starts in /work/srvros-work; use a fresh filename such as desktop-trial.txt. Close the document, then open it from Files at that same location and check every line. Add a short note about anything that failed and save again. /fat is RAM: files saved there disappear on reboot."),
 H(9,"4. Exercise the apps"),P(10,"In Terminal try seq 1 2000, then exit. While output scrolls, type in Text and move the pointer. Try Calculator, Settings, Sketch and Clock. Command-Shift-3 saves a screenshot directly into Home > Screenshots on USB; open it in Preview. Close unused windows: eight can be open at once. Change a setting and wait for confirmation that preferences are saved. On the following trial boot, check that the setting returns."),
 H(11,"5. Finish and return"),P(12,"Save your USB document and exit the Terminal shell. Choose SrvrOS > Return to console. The trial flushes and unmounts the USB volume. Photograph an error if one appears. Once the console says USB unmounted=yes, type reboot to return to Ubuntu, then tell us how it behaved."),
 H(20,"Sound checks for this round"),P(21,"In Settings, scroll to Sound. Leave the volume at 25% and choose Test sound. Listen for one short tone from both built-in speakers, then silence. Try it twice. Change the volume to a comfortable lower level and test again. Type and move the pointer while triggering the tone; input should remain responsive. If you have wired headphones, plug them in, check that the connection label changes, select Headphones and test at low volume. The speakers should stay silent. Select Speakers after unplugging. No audio should start by itself. Note which output worked and any noise, missing channel or stuck tone. Use Stop if needed. Then open Terminal and run playwav /fat/share/examples/stereo.wav. The six-second sample plays left, right, then both channels, with silence between sections. Type in Text or move a window while it plays. Stop in Settings should cancel playback. This is an output-only test; microphone access is not enabled."),
 H(23,"Devices and temperatures"),P(24,"Open System and choose Devices. Check that the built-in keyboard, trackpad and flash drive appear with active drivers. Choose Sensors: CPU core and package temperatures should update about once a second, with a recent sample age. Pause and Refresh work here too. Fan speed should also have a recent sample age and an RPM reading. Battery availability depends on the boot profile; this guided device trial leaves monitoring off. Take a screenshot of Sensors and note if values stay unavailable or become stale. If a USB network adapter is attached before boot, Devices shows its identifiers; only CDC ECM adapters have this first USB networking driver."),
 H(16,"Saved diagnostics"),P(17,"This trial saves boot information and periodic diagnostic snapshots in Home > Logs, with a separate folder for each session. After returning to Ubuntu we can collect them directly from the flash drive. If the desktop freezes, the most recent snapshot may be incomplete; a photo is still useful. Power-controller diagnostics are collected automatically. In Settings, scroll below Trackpad to Display brightness. Try 20%, 50%, then a comfortable level while typing and moving the pointer. Brightness applies to this session; startup does not change it. Ordinary battery monitoring uses a separate accepted Home profile."),
 N(13,"For a stuck desktop, Ctrl-Alt-Escape returns to the console without saving unfinished edits. The trial will still attempt to flush and unmount the USB workspace. Network and battery acceptance remain specific to the recorded device/profile.")};
